result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/seqfmt.py", "content": "#!/usr/bin/env python3
"""Quick sequence-format tools with round-trip guarantees.

Subcommands:
    fq2fa        convert FASTQ to FASTA
    wrap N       rewrap FASTA sequence lines to N columns
    unwrap       put each FASTA sequence on a single line

Malformed FASTQ input fails with an error naming the offending record number.
"""

from __future__ import annotations

import argparse
import sys
from typing import Iterator, List, Tuple


class FormatError(Exception):
    """Raised when input is malformed."""


# ---------------------------------------------------------------- FASTA I/O

def read_fasta(lines: Iterator[str]) -> Iterator[Tuple[str, List[str]]]:
    """Yield (header_line_including_'>', [sequence chunks])."""
    header = None
    chunks: List[str] = []
    for lineno, raw in enumerate(lines, 1):
        line = raw.rstrip("\n").rstrip("\r")
        if not line:
            continue
        if line.startswith(">"):
            if header is not None:
                yield header, chunks
            header = line
            chunks = []
        else:
            if header is None:
                raise FormatError(f"line {lineno}: sequence data before first FASTA header")
            chunks.append(line)
    if header is not None:
        yield header, chunks


def write_fasta_record(out, header: str, chunks: List[str], width: int | None) -> None:
    """Emit one FASTA record; width=None puts the whole sequence on one line."""
    out.write(header + "\n")
    seq = "".join(chunks)
    if width is None:
        out.write(seq + "\n")
    else:
        for i in range(0, len(seq), width):
            out.write(seq[i:i + width] + "\n")


# ---------------------------------------------------------------- FASTQ I/O

def read_fastq(lines: List[str]) -> Iterator[Tuple[str, str]]:
    """Yield (id, sequence) from a strict 4-line-per-record FASTQ."""
    n_records = 0
    i = 0
    while i < len(lines):
        line = lines[i].rstrip("\r\n")
        if not line:
            i += 1
            continue
        rec = n_records + 1
        if len(lines) - i < 4:
            raise FormatError(
                f"record {rec}: truncated FASTQ record (expected 4 lines, got {len(lines) - i})"
            )
        header, seq, sep, qual = (lines[i + k].rstrip("\r\n") for k in range(4))
        if not header.startswith("@"):
            raise FormatError(f"record {rec}: expected '@' at start of header line")
        if not sep.startswith("+"):
            raise FormatError(f"record {rec}: bad separator line (expected '+', got {sep[:1]!r})")
        if len(qual) != len(seq):
            raise FormatError(
                f"record {rec}: sequence/quality length mismatch "
                f"(seq={len(seq)}, qual={len(qual)})"
            )
        yield header[1:], seq
        n_records += 1
        i += 4


# ---------------------------------------------------------------- commands

def cmd_fq2fa(args: argparse.Namespace) -> int:
    with open(args.input) as fh:
        fastq_lines = fh.readlines()
    with open(args.output, "w") as out:
        try:
            for rec_id, seq in read_fastq(fastq_lines):
                out.write(f">{rec_id}\n{seq}\n")
        except FormatError as exc:
            sys.exit(f"error: {args.input}: {exc}")
    return 0


def cmd_wrap(args: argparse.Namespace) -> int:
    with open(args.input) as fh, open(args.output, "w") as out:
        try:
            for header, chunks in read_fasta(fh):
                write_fasta_record(out, header, chunks, args.width)
        except FormatError as exc:
            sys.exit(f"error: {args.input}: {exc}")
    return 0


def cmd_unwrap(args: argparse.Namespace) -> int:
    with open(args.input) as fh, open(args.output, "w") as out:
        try:
            for header, chunks in read_fasta(fh):
                write_fasta_record(out, header, chunks, None)
        except FormatError as exc:
            sys.exit(f"error: {args.input}: {exc}")
    return 0


def main(argv: List[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="seqfmt", description=__doc__)
    sub = parser.add_subparsers(dest="command", required=True)

    p = sub.add_parser("fq2fa", help="convert FASTQ to FASTA")
    p.add_argument("input")
    p.add_argument("output")
    p.set_defaults(func=cmd_fq2fa)

    p = sub.add_parser("wrap", help="rewrap FASTA sequences to N columns")
    p.add_argument("width", type=int)
    p.add_argument("input")
    p.add_argument("output")
    p.set_defaults(func=cmd_wrap)

    p = sub.add_parser("unwrap", help="put each FASTA sequence on one line")
    p.add_argument("input")
    p.add_argument("output")
    p.set_defaults(func=cmd_unwrap)

    args = parser.parse_args(argv)
    return args.func(args)


if __name__ == "__main__":
    sys.exit(main())
"})
